using FlexExtractor;
using System.Security.AccessControl;
using System.Security.Principal;
static partial class Cases {
 static void DeniedBranch(Action<Config,string> assertion,List<string> selected){var c=Cfg(Fresh());c.SizeStableChecks=0;c.DispenseItems[0].SubFolders=selected;var good=Source(c,"good/deep/Request_healthy.xml");var blocked=Path.Combine(Path.GetDirectoryName(Path.GetDirectoryName(good))!,"..","blocked");blocked=Path.GetFullPath(blocked);Directory.CreateDirectory(blocked);var rule=new FileSystemAccessRule(WindowsIdentity.GetCurrent().User!,FileSystemRights.ReadAndExecute,AccessControlType.Deny);var acl=new DirectoryInfo(blocked).GetAccessControl();acl.AddAccessRule(rule);new DirectoryInfo(blocked).SetAccessControl(acl);try{assertion(c,good);}finally{var restored=new DirectoryInfo(blocked).GetAccessControl();restored.RemoveAccessRuleSpecific(rule);new DirectoryInfo(blocked).SetAccessControl(restored);}}
 public static void TestReviewTraversalSkipsUnselectedDeniedBranch(){DeniedBranch((c,good)=>{using var lease=new OwnerLease();for(int i=0;i<3;i++){var r=WorkerRunner.RunAsync(lease,c,"scan",DateTime.UtcNow,CancellationToken.None).GetAwaiter().GetResult();Program.Check(r.Failed==0,"unselected inaccessible branch was visited: "+string.Join(" | ",r.Messages));}Program.Check(Directory.GetFiles(c.DispenseItems[0].SaveFolder,"Request*.xml").Length==1,"healthy selected subtree starved");Program.Check(File.ReadAllText(good).Contains("header"),"source changed");},["good"]);}
 public static void TestReviewTraversalAllSelectionIsolatesDeniedBranch(){DeniedBranch((c,good)=>{for(int i=0;i<3;i++){var r=(ScanResult)Scan(c);Program.Check(r.Failed>0&&r.Messages.Count<=32,"selected directory failure not bounded/visible");}Program.Check(Directory.GetFiles(c.DispenseItems[0].SaveFolder,"Request*.xml").Length==1,"healthy all-selection branch starved");},[]);}
 public static void TestReviewTraversalSelectedDeniedBranchDoesNotBlockSibling(){DeniedBranch((c,good)=>{c.MaxFilesPerPass=1;var failed=0;for(int i=0;i<5;i++){var r=(ScanResult)Scan(c);failed+=r.Failed;Program.Check(r.Messages.Count<=32,"unbounded errors");}Program.Check(failed>0,"selected denied branch not reported");Program.Check(Directory.GetFiles(c.DispenseItems[0].SaveFolder,"Request*.xml").Length==1,"healthy selected branch starved by permanent directory fault");},["blocked","good/deep"]);}
}
